<script setup lang="ts">export type ProfileDetail={label:string;value:string};defineProps<{name:string;subtitle?:string;image?:string;details?:ProfileDetail[];status?:string}>()</script><template><article class="vx-profile"><header class="vx-profile__header"><img v-if="image" :src="image" :alt="name"/><span v-else class="vx-profile__avatar" aria-hidden="true">{{name.charAt(0).toUpperCase()}}</span><div><h2>{{name}}</h2><p v-if="subtitle">{{subtitle}}</p><small v-if="status">{{status}}</small></div><slot name="actions"/></header><dl v-if="details?.length" class="vx-profile__details"><div v-for="d in details" :key="d.label"><dt>{{d.label}}</dt><dd>{{d.value}}</dd></div></dl><slot/></article></template>
